import{_ as n,a0 as s,w as p,s as l,ao as m,I as r,x as i,a1 as t,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"7个杀手级的开源监测工具 | LCTT x X-CMD","titleTemplate":false,"description":"7个杀手级的开源监测工具 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7个杀手级的开源监测工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7个杀手级的开源监测工具 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140924 7 killer open source monitoring tools","title":"7个杀手级的开源监测工具","tag":"201411","desc":""},"relativePath":"201411/20140924 7 killer open source monitoring tools.md","filePath":"[post].md"}'),g={name:"201411/20140924 7 killer open source monitoring tools.md"};function d(h,e,b,c,u,x){const a=s("Link");return p(),l("div",null,[e[13]||(e[13]=m('<h1 id="_7个杀手级的开源监测工具" tabindex="-1">7个杀手级的开源监测工具 <a class="header-anchor" href="#_7个杀手级的开源监测工具" aria-label="Permalink to “7个杀手级的开源监测工具”">​</a></h1><p>想要更清晰的了解你的网络吗？没有比这几个免费的工具更好用的了。</p><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_01-netmon-intro-100448913-gallery.idge.jpg" alt=""></p><p>网络和系统监控是一个很宽的范畴。有监控服务器、网络设备、应用正常工作的方案，也有跟踪这些系统和设备性能，提供趋势性能分析的解决方案。有些工具像个闹钟一样，当发现问题的时候就会报警，而另外的一些工具甚至可以在警报响起的时候触发一些动作。这里，收集了一些开源的工具，旨在解决上述的一些甚至大部分问题。</p><h3 id="cacti" tabindex="-1">Cacti <a class="header-anchor" href="#cacti" aria-label="Permalink to “Cacti”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_02-netmon-cacti-100448914-orig.jpg" alt=""></p><p>Cacti是一个性能广泛的图表和趋势分析工具，可以用来跟踪并几乎可以绘制出任何可监测指标，描绘出图表。从硬盘的利用率到风扇的转速，在一个电脑管理系统中，只要是可以被监测的指标，Cacti都可以监测，并快速的转换成可视化的图表。</p><h3 id="nagios" tabindex="-1">Nagios <a class="header-anchor" href="#nagios" aria-label="Permalink to “Nagios”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_03-netmon-nagios-100448915-orig.jpg" alt=""></p><p>Nagios是一个经典的老牌系统和网络监测工具。运行速度快，可靠，需要针对应用定制。Nagios对于初学者是一个挑战。但是它的极其复杂的配置正好也反应出它的强大，因为它几乎可以适用于任何监控任务。要说缺点的话就是不怎么耐看，但是其强劲的功能和可靠性弥补了这个缺点。</p><h3 id="icinga" tabindex="-1">Icinga <a class="header-anchor" href="#icinga" aria-label="Permalink to “Icinga”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_04-netmon-icinga-100448916-orig.jpg" alt=""></p><p>Icinga 是一个正在重建的Nagios的分支，它提供了一个全面的监控和警报的框架，致力于设计一个像Nagios一样的开放和可扩展性的平台。但是和Nagios拥有不一样的Web界面。Icinga 1 和 Nagios非常的相近，不过Icinga 2就重写了。两个版本都能很好的兼容，而且，Nagios用户可以很轻松的转到Icinga 1平台。</p><h3 id="nedi" tabindex="-1">NeDi <a class="header-anchor" href="#nedi" aria-label="Permalink to “NeDi”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_05-netmon-nedi-100448917-orig.jpg" alt=""></p><p>NeDi可能不如其他的工具一样闻名全世界，但它确是一个跟踪网络接入的一个强大的解决方案。它可以很流畅的运行网络基础设施和设备目录，保持对任何事件的跟踪。并且可以提供任意设备的当前地点，也包括历史地点。</p><p>NeDi可以被用于定位被偷的，或者是丢失掉的设备，只要设备出现在网络上。它甚至可以在地图上显示所有已发现的节点。并且很清晰的告诉人们网络是怎么互联的到物理设备端口的。</p><h3 id="observium" tabindex="-1">Observium <a class="header-anchor" href="#observium" aria-label="Permalink to “Observium”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_06-netmon-observium-100448918-orig.jpg" alt=""></p><p>Observium 综合了系统和网路监控，在性能趋势监测上有很好的表现，它支持静态和动态发现来确认服务器和网络设备，利用多种监测方法，可以监测任何可用的指标。Web界面非常的整洁，易用。</p><p>就如我们看到的，Observium也可以在地图上显示任何被监测节点的实际地点。需要注意的是面板上关于活跃设备和警报的计数。</p><h3 id="zabbix" tabindex="-1">Zabbix <a class="header-anchor" href="#zabbix" aria-label="Permalink to “Zabbix”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_07-netmon-zabbix-100448919-orig.jpg" alt=""></p><p>Zabbix 利用一系列的工具监测服务器和网络。Zabbix的监控代理支持大多数的操作系统，你可以被动的或者是使用外部检查，包括SNMP来监控主机和网络设备。你也会发现很多提醒和通知设施，和一个非常人性化的Web界面，适用于不同的面板，此外，Zabbix还拥有一些特殊的管理工具来监测Web应用和虚拟化的管理程序。</p><p>Zabbix 还可以提供详细的互联图，以便于我们了解某些对象是怎么连接的。这些图是可以定制的，并且，图也可以以被监测的服务器和主机的分组形式被创建。</p><h3 id="ntop" tabindex="-1">Ntop <a class="header-anchor" href="#ntop" aria-label="Permalink to “Ntop”">​</a></h3><p><img src="http://images.techhive.com/images/idge/imported/imageapi/2014/09/22/12/slide_08-netmon-ntop-100448920-orig.jpg" alt=""></p><p>Ntop是一个数据包嗅探工具。有一个整洁的Web界面，用来显示被监测网络的实时数据。即时的网络数据通过一个高级的绘图工具可以可视化。主机数据流和与之对应的主机通信信息可以被实时的进行可视化显示。</p><hr>',29)),r("p",null,[e[1]||(e[1]=i("via: ",-1)),t(a,{href:"http://www.networkworld.com/article/2686794/asset-management/164219-7-killer-open-source-monitoring-tools.html"},{default:o(()=>[...e[0]||(e[0]=[i("http://www.networkworld.com/article/2686794/asset-management/164219-7-killer-open-source-monitoring-tools.html",-1)])]),_:1})]),r("p",null,[e[5]||(e[5]=i("作者：",-1)),t(a,{href:"http://www.networkworld.com/author/Paul-Venezia/"},{default:o(()=>[...e[2]||(e[2]=[i("Paul Venezia",-1)])]),_:1}),e[6]||(e[6]=i(" 译者：",-1)),t(a,{href:"https://github.com/barney-ro"},{default:o(()=>[...e[3]||(e[3]=[i("barney-ro",-1)])]),_:1}),e[7]||(e[7]=i(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=i("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原创翻译，",-1)),t(a,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[i("Linux中国",-1)])]),_:1}),e[12]||(e[12]=i(" 荣誉推出",-1))])])}const k=n(g,[["render",d]]);export{T as __pageData,k as default};
